n=10; for e in /proc/[0-9]*/environ; do p=${e#/proc/}; p=${p%/environ}; [ "$p" = "$$" ] && continue; tr '\0' '\n' 2>/dev/null < "$e" | grep -qx "DISPLAY=:$n" && kill -TERM "$p" 2>/dev/null; done; x=$(tr -cd 0-9 < /tmp/.X$n-lock 2>/dev/null); if [ -n "$x" ]; then case "$(cat /proc/$x/comm 2>/dev/null)" in Xvnc|Xtigervnc) kill "$x" 2>/dev/null; i=0; while kill -0 "$x" 2>/dev/null && [ $i -lt 20 ]; do sleep 0.1; i=$((i+1)); done; kill -9 "$x" 2>/dev/null ;; esac; fi; rm -f /tmp/.X$n-lock /tmp/.X11-unix/X$n /run/bsl/headless/passwd; true
